/* Source-linked corrections and matching; unresolved policy cases remain held. */
let replacement107=null;
function oldReplacement107(id){const c=model107().replacements?.find(c=>c.id===id);if(!c||isLabel10()&&!c.oldRows.some(r=>r.member===ten.member))return;reviewDialogUI(tr107('Versi laporan sebelumnya','Previous report version'),`<div class="royalty107"><p class="note107">${tr107('Digantikan oleh versi terbaru','Replaced by the latest version')} · ${E(c.batch)} / v${c.version}</p>${trackTable107(c.oldRows.filter(r=>!isLabel10()||r.member===ten.member),false)}</div>`)}
function allocations107(){if(ten.role!=='super')return;const s=model107();reviewDialogUI(tr107('Penerimaan dana','Received funds'),`<div class="royalty107">${s.receipts.map(r=>{const used=r.allocations.reduce((n,a)=>n+a.amount,0);return `<section class="note107"><div class="history107"><div><strong>${E(r.reference)}</strong><small style="display:block">${E(r.date)} · ${money107(r.amount)}</small></div>${used<r.amount?btn107(tr107('Cocokkan laporan','Match reports'),'allocate',r.id,'primary'):pill107(tr107('Dicocokkan','Matched'),'green')}</div><p>${tr107('Belum dialokasikan','Unallocated')}: ${money107(r.amount-used)}</p>${r.allocations.map(a=>`<small style="display:block">${E(a.batch)} · ${E(memberName107(a.member))} · ${money107(a.amount)}</small>`).join('')}</section>`}).join('')||empty107(tr107('Belum ada penerimaan dana tercatat.','No receipts recorded.'))}<p class="muted107">${tr107('Sisa penerimaan tidak dibagikan otomatis.','Remaining funds are never allocated automatically.')}</p></div>`)}
function allocateDialog107(id){if(ten.role!=='super')return;const s=model107(),r=s.receipts.find(r=>r.id===id);if(!r)return;reviewDialogUI(tr107('Cocokkan penerimaan','Match receipt'),`<form class="form107" data-ops107="allocate" data-version="${s.version}" data-id="${id}"><h3>${E(r.reference)} · ${money107(r.amount-r.allocations.reduce((n,a)=>n+a.amount,0))}</h3>${s.batches.flatMap(b=>b.posted.map(m=>{const amount=s.ledger.filter(l=>l.ref===b.id&&l.member===m&&l.bucket==='pending').reduce((n,l)=>n+l.amount,0);return amount>0?`<label class="check107"><input type="checkbox" name="targets" value="${b.id}|${m}"><span>${E(b.name)}<br>${E(memberName107(m))} · ${money107(amount)}</span></label>`:''})).join('')}<label class="check107"><input type="checkbox" name="checked" required><span>${tr107('Bagian laporan yang dipilih sudah dicocokkan dengan bukti penerimaan ini.','The selected report portions match this receipt evidence.')}</span></label>${err107}<button class="btn primary">${tr107('Konfirmasi pencocokan','Confirm matching')}</button></form>`)}
function replacementDialog107(id,mode='file'){if(ten.role!=='super')return;const b=Royalty107.batch(model107(),id);reviewDialogUI(mode==='file'?tr107('Ganti file laporan','Replace report file'):tr107('Koreksi pencocokan katalog','Correct catalogue mapping'),`<form class="form107" data-ops107="${mode==='file'?'replace-file':'replace-mapping'}" data-id="${id}">${mode==='file'?`<label>${tr107('CSV pengganti','Replacement CSV')}<input type="file" name="file" accept=".csv" required></label><p class="note107">${tr107('Penggantian memakai kurs dan dasar perhitungan laporan asal. Unggahan belum mengubah laporan atau saldo.','Replacement uses the original rate and calculation basis. Uploading does not change reports or balances.')}</p>`:`<label>${tr107('Baris yang dikoreksi','Source row')}<select name="row">${b.rows.map(r=>opt107(r.id,r.title+' · '+memberName107(r.member)+' · '+r.platform,'')).join('')}</select></label><label>${tr107('Katalog dan pemilik yang benar','Correct catalogue and owner')}<select name="target">${candidates107().map((c,i)=>opt107(String(i),memberName107(c.member)+' · '+c.title+' · '+c.isrc,'')).join('')}</select></label>`}<label>${tr107('Alasan dan referensi sumber','Reason and source reference')}<textarea name="reason" required rows="3"></textarea></label>${err107}<button class="btn primary">${tr107('Bandingkan perubahan','Compare changes')}</button></form>`)}
function replacementPreview107(p){const b=Royalty107.batch(model107(),p.id),members=[...new Set([...b.rows,...p.rows].map(r=>r.member))];replacement107={...p,expectedVersion:model107().version};reviewDialogUI(tr107('Perbandingan laporan','Report comparison'),`<form class="form107 royalty107" data-ops107="apply-replacement"><div class="table107"><table><thead><tr><th>Label</th><th>${tr107('Sebelumnya','Before')}</th><th>${tr107('Setelah koreksi','After')}</th><th>${tr107('Perubahan','Change')}</th></tr></thead><tbody>${members.map(m=>{const old=total107(b.rows.filter(r=>r.member===m)),next=total107(p.rows.filter(r=>r.member===m));return `<tr><td>${E(memberName107(m))}</td><td>${money107(old)}</td><td>${money107(next)}</td><td>${money107(next-old)}</td></tr>`}).join('')}</tbody></table></div><p>${E(p.reason)}</p><p class="note107">${tr107('Versi lama tetap tersimpan. Jika ada penarikan terkait atau saldo tidak mencukupi, perubahan ditahan untuk penyelesaian. Tambahan pendapatan menunggu pencocokan dana sebelum tersedia.','Prior versions are retained. Related withdrawals or insufficient balances hold the correction for resolution. Additional earnings await receipt matching before becoming available.')}</p>${err107}<button class="btn primary">${tr107('Terapkan koreksi','Apply correction')}</button></form>`)}
function cases107(){if(ten.role!=='super')return;reviewDialogUI(tr107('Koreksi memerlukan penyelesaian','Corrections requiring resolution'),`<div class="royalty107">${model107().cases.map(c=>`<section class="note107"><strong>${E(c.batch)} · ${c.member?E(memberName107(c.member)):tr107('Koreksi laporan','Report correction')}</strong><p>${E(c.reason)}</p>${c.diff?c.diff.map(x=>`<p>${E(memberName107(x.member))}: ${money107(x.delta)}</p>`).join(''):`<p>${money107(c.before)} → ${money107(c.after)}</p>`}<small>${date107(c.at)}</small><p>${tr107('Saldo dan riwayat pembayaran tidak diubah. Kebijakan penyelesaian setelah pembayaran belum final.','Balances and payout history remain unchanged. Post-payout resolution policy is not final.')}</p></section>`).join('')||empty107(tr107('Belum ada koreksi tertahan.','No held corrections.'))}</div>`)}
const detailOps107=batchDetail107;batchDetail107=function(){const html=detailOps107();if(ten.role!=='super')return html;const t=document.createElement('template');t.innerHTML=html;const b=Royalty107.batch(model107(),ui107.batch),body=t.content.querySelector('.panel107');if(ui107.detailTab==='summary')body.insertAdjacentHTML('beforeend',`<div class="actions107">${btn107(tr107('Penerimaan & pencocokan','Receipts & matching'),'receipts')}${!b.posted.length?btn107(tr107('Arsipkan laporan belum terbit','Archive unpublished report'),'archive-report',b.id,'text'):''}${b.posted.length?btn107(tr107('Ganti file laporan','Replace report file'),'replace-file',b.id,'text')+btn107(tr107('Koreksi katalog','Correct mapping'),'replace-mapping',b.id,'text'):''}${model107().cases.length?btn107(tr107('Koreksi tertahan','Held corrections')+' · '+model107().cases.length,'cases','','text'):''}</div>`);return t.innerHTML};
const reportOps107=report107;report107=function(period){reportOps107(period);const el=document.querySelector('#dialog .royalty107');if(!el)return;const replacements=(model107().replacements||[]).filter(c=>c.oldRows.some(r=>r.period===period&&(!isLabel10()||r.member===ten.member)));if(replacements.length)el.insertAdjacentHTML('beforeend',`<h3>${tr107('Riwayat penggantian','Replacement history')}</h3>${replacements.map(c=>`<div class="history107"><div><strong>${E(c.batch)} / v${c.version}</strong><p>${E(c.reason)}</p><small>${date107(c.at)}</small></div>${btn107(tr107('Lihat versi','View version'),'old-replacement',c.id)}</div>`).join('')}`)};
const attentionOps107=labelAttention102;labelAttention102=function(){return attentionOps107()+(model107().replacements||[]).filter(c=>c.diff.some(x=>x.member===ten.member&&x.delta)).map(c=>{const delta=c.diff.find(x=>x.member===ten.member).delta;return `<section class="attention9 attention-card106"><h2>${tr107('Laporan royalti diperbarui','Royalty report updated')}</h2><p>${money107(delta)} · ${E(c.reason)}</p>${btn107(tr107('Lihat laporan','View report'),'report',c.oldRows.find(r=>r.member===ten.member)?.period||'2026-09')}</section>`}).join('')};
window.addEventListener('click',e=>{const b=e.target.closest('[data-r107]');if(!b)return;const a=b.dataset.r107,id=b.dataset.id;if(a==='archive-report'&&ten.role==='super'){reviewDialogUI(tr107('Arsipkan laporan','Archive report'),`<form class="form107" data-ops107="archive" data-id="${E(id)}"><p>${tr107('Hanya laporan yang belum terbit dapat diarsipkan. Sumber dan riwayat dipertahankan; laporan ini tidak lagi digunakan dalam penerbitan.','Only unpublished reports can be archived. Sources and history are retained; this report is excluded from publication.')}</p><label>${tr107('Alasan pengarsipan','Reason for archiving')}<textarea name="note" required></textarea></label>${err107}<button class="btn primary">${tr107('Konfirmasi pengarsipan','Confirm archive')}</button></form>`);return}if(a==='receipts')allocations107();if(a==='allocate')allocateDialog107(id);if(a==='replace-file')replacementDialog107(id);if(a==='replace-mapping')replacementDialog107(id,'mapping');if(a==='cases')cases107();if(a==='old-replacement'){const c=model107().replacements?.find(c=>c.id===id);if(!c||isLabel10()&&!c.oldRows.some(r=>r.member===ten.member))return;reviewDialogUI(tr107('Versi laporan sebelumnya','Previous report version'),`<div class="royalty107"><p class="note107">${tr107('Digantikan oleh versi terbaru','Replaced by the latest version')} · ${E(c.batch)} / v${c.version}</p>${trackTable107(c.oldRows.filter(r=>!isLabel10()||r.member===ten.member),false)}</div>`)}},true);
window.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.ops107)return;e.preventDefault();e.stopImmediatePropagation();if(!f.reportValidity()||ten.role!=='super')return;const fd=new FormData(f),p=Object.fromEntries(fd),id=f.dataset.id,kind=f.dataset.ops107,submit=e.submitter;if(submit)submit.disabled=true;try{
 if(kind==='archive'){post107('archive',{id,note:p.note});ui107.batch=null;closeModal();render();return;}if(kind==='allocate')post107('allocate',{id:ui107.batch,receipt:id,targets:fd.getAll('targets'),checked:!!p.checked,expectedVersion:+f.dataset.version});
 if(kind==='replace-file'){const b=Royalty107.batch(model107(),id),parsed=await parseImport107(fd.get('file'),b.rate,b.share);replacementPreview107({id,rows:parsed.rows,fingerprint:parsed.fingerprint,reason:p.reason});return;}
 if(kind==='replace-mapping'){const b=Royalty107.batch(model107(),id),c=candidates107()[+p.target],rows=structuredClone(b.rows),r=rows.find(r=>r.id===p.row);if(!r||!c)throw Error('Pilih data sumber dan tujuan.');Object.assign(r,{member:c.member,track:c.id,isrc:c.isrc,matched:true});replacementPreview107({id,rows,reason:p.reason});return;}
 if(kind==='apply-replacement'){if(!replacement107)throw Error('Tinjau ulang koreksi.');const result=post107('replace',replacement107);replacement107=null;closeModal();render();toast(result==='review'?tr107('Koreksi ditahan untuk penyelesaian.','Correction held for resolution.'):tr107('Koreksi diterapkan.','Correction applied.'));return;}
 closeModal();render();toast(tr107('Pencocokan tersimpan.','Matching saved.'));
}catch(err){formError107(err)}finally{if(submit)submit.disabled=false}},true);
